let trustState={caseId:'',step:0,questions:0,blind:null,judgment:null,source:null,accept:[],recomputed:false};
function trustCard(c){return `<a class="trust-case-card" href="#verify/${c.id}"><div class="trust-case-top"><span>${c.icon} / ${c.kind}</span><b>7 步练习</b></div><h3>${c.title}</h3><p>${c.desc}</p><div class="trust-case-flow"><span>A 先做</span><span>B 独立查</span><span>查原文</span><span>再检查</span></div><strong>开始练习</strong></a>`;}
function coreLessonLinks(){return '<ol class="core-lesson-links">'+CORE_LESSONS.map((i,n)=>`<li><a href="#lesson/${i}"><span>${String(n+1).padStart(2,'0')}</span>${LESSONS[i].title}</a></li>`).join('')+'</ol>';}
function trustHome(){return `<div class="welcome"><div><h1>AI 入门教程</h1><p>从怎么提问，到怎么检查结果，跟着例子一步一步学。不需要编程基础。</p></div><span class="tag">适合第一次用 AI 的你</span></div>
${resumeLesson()}<section class="trust-hero"><div><div class="eyebrow">第一部分 · 先学方法</div><h2>怎样放心用 AI</h2><p>先学会说清想做什么、让 AI 补问细节，再看看怎样检查回答。下面五课按这个顺序讲，建议先从第一课开始。</p><div class="actions">${button('开始第一课','#lesson/11')}${button('查看本部分说明','#trust','secondary')}</div><p class="small-note"><a href="#lesson/0">还没用过 AI？先认识工具</a> · <a href="#help">看不懂时怎么问</a></p></div><div class="trust-hero-board"><strong>这一部分有哪几课？</strong>${coreLessonLinks()}</div></section>
<ol class="trust-path" aria-label="使用 AI 的六个步骤">${['说清想做什么','让 AI 问你','说好怎么检查','问清出处','换个 AI 检查','改完再试一次'].map((x,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span>${x}</li>`).join('')}</ol>
<section id="home-methods"><div class="section-head"><div><h2>方法课程</h2><p>每课讲一件事。说不清需求、看不懂回答、担心它做错，都可以从这里开始。</p></div><a href="#courses">全部 ${LESSONS.length} 节课</a></div><div class="grid three">${CORE_LESSONS.map(i=>courseCard(LESSONS[i],i)).join('')}</div></section>
<section id="home-practice"><div class="section-head"><div><div class="eyebrow">第二部分 · 用例子练一练</div><h2>跟着这三个例子，学会检查回答</h2><p>学过方法后，再读材料、比较几个 AI 的回答，试着找出问题。</p></div></div><div class="grid three">${TRUST_CASES.map(trustCard).join('')}</div></section>
<section id="home-applications"><div class="section-head"><div><div class="eyebrow">第三部分 · 做自己的事情</div><h2>学会以后，可以用来做什么？</h2><p>做课件、写通知、读文献、研究股票……这里有 ${DEMOS.length} 个可以跟着做的例子。</p></div><a href="#scenes">浏览全部演示</a></div><div class="grid three">${[DEMOS[6],DEMOS[2],DEMOS[5]].map(demoCard).join('')}</div></section><section class="site-story-link"><div><span class="eyebrow">这个网站本身，也是一个例子</span><h2>这些页面，也是请 AI 一步步做出来的。</h2><p>作者没有手工编写网页代码，而是提出需求、看效果、继续修改。你可以看看实际经历了哪些步骤。</p></div>${button('看看制作过程','#about','secondary')}</section>`;}
function trustPage(){return heading('方法总览','怎样放心用 AI','这部分包括五课：从交代事情、继续提问，到查出处、换一个 AI 检查和改完后再试一次。先学方法，再跟着例子练习。')+`<div class="learning-shortcuts"><a href="#lesson/0">还没用过 AI？先认识工具</a><a href="#help">没听懂？看看怎么问</a></div><section class="card"><h2>先学这五课</h2>${coreLessonLinks()}<p class="small-note">这里与首页的方法课程相同，点击课程名称进入正文。下面是这些方法的简要说明。</p></section><div class="trust-principle"><strong>先做一小部分，看看合不合你的意思。</strong><p>例如做 PPT 时，先看一页；写通知时，先看一段。发现问题就具体告诉它。确认方向对了，再让它继续。</p></div><div class="grid three">${[
 ['01','先说想做什么','告诉它给谁用、想做成什么样、有哪些材料。还有哪些事需要先问你，也一起说清楚。','先说说你理解的任务，再告诉我还缺哪些信息。'],
 ['02','说不清，就让它问你','不必一开始就想得很完整。可以让 AI 问用途、对象和要求，你一次回答一个问题。','我还没想清楚，你先问我一个问题，给几个容易理解的选项。'],
 ['03','说好做成什么样','把“做好一点”说具体。比如通知控制在一页、课件讲五分钟、清单勾选后能计数。','先做一小部分给我看看。做完后，再告诉我哪些地方需要检查。'],
 ['04','问一句：这是从哪来的？','重要的说法要看原文，数字要重新算，文件要自己打开。只说“检查过了”还不够。','这句话的出处在哪里？请给我原文位置，查不到就直接说。'],
 ['05','换一个 AI 再看看','先让另一个 AI 自己读材料、算一遍，再给它看第一个 AI 的答案，比较哪里不同。','请先自己检查这份材料，再看看有没有不符合材料的说法。'],
 ['06','改好了，再试一次','重新检查刚才出错的地方，也看看有没有改坏别的地方。重要信息没查清，就先别用。','请把刚才出错的操作再试一次，告诉我现在是什么结果。']
 ].map(([n,t,p,q])=>`<section class="card method-card"><span class="method-number">${n}</span><h3>${t}</h3><p>${p}</p><blockquote>${q}</blockquote></section>`).join('')}</div><div class="section-head"><h2>几个 AI 都说对，就一定对吗？</h2></div><div class="grid two"><section class="card"><h3>这些东西值得检查</h3><ul><li>原文是哪一段，什么时候发布，适用于什么情况。</li><li>数字是怎么算的，用的是哪一份数据。</li><li>实际点了什么、应该出现什么、最后出现了什么。</li><li>哪些情况和它说的不一样，哪些地方还没查清。</li></ul></section><section class="card"><h3>光看这些还不够</h3><ul><li>“我非常确定”“我检查了三遍”。</li><li>三个 AI 说法一致，但都没有看原文。</li><li>很多链接，其实转引同一个错误说法。</li><li>反对者语气强硬，却拿不出依据。</li></ul></section></div><div class="callout">几个 AI 可能看了同一份资料，也可能犯同样的错。遇到重要问题，不妨打开原文、自己算一次，或实际试一下，别只反复问“你确定吗”。</div><div class="section-head" id="trust-practice"><h2>跟着例子做一遍</h2></div><div class="grid three">${TRUST_CASES.map(trustCard).join('')}</div><div class="section-head" id="trust-questions"><h2>换成你自己的事情，试着说一说</h2></div>${delegationForm()}<section class="card" style="margin-top:24px"><h2>什么时候可以停？</h2><p>先看开始时说好的要求是否都做到了。重要的数字和事实查清了，文件也试过了，就可以按这次检查的范围使用。还有关键问题没弄明白，就补材料或请懂这件事的人帮忙，不必让几个 AI 一直争论下去。</p><p class="small-note">上面的流程是本课堂整理的实践方法，不是准确率保证。提问与自行审阅可参阅 <a href="https://learn.chatgpt.com/docs/prompting" target="_blank" rel="noopener noreferrer">OpenAI 官方指南</a>；AI 迎合用户观点的风险可参阅 <a href="https://www.anthropic.com/research/towards-understanding-sycophancy-in-language-models" target="_blank" rel="noopener noreferrer">Anthropic 的相关研究</a>。</p></section>`;}
function delegationForm(){return `<section class="card"><form id="delegation-form"><div class="form-grid">${field('你想做什么？','goal','例如：一份 5 页的课程汇报 PPT')}${field('给谁用？','audience','例如：通识课同学，讲述 5 分钟')}</div>${field('手头有哪些材料？','sources','写文件名、版本、日期；暂时没有就说明',true)}<div class="form-grid">${field('怎样才算合格？','criteria','例如：每个数字能回查；5 分钟讲完；实际打开检查',true)}${field('哪些事可以直接做，哪些要先问你？','boundary','例如：可整理副本、做小样；不能覆盖原件或替我提交',true)}</div><button class="btn" type="submit">整理成几段可以直接用的提问</button><p class="small-note">只在本地整理文本，不会发送给任何 AI；切换页面前请复制需要的内容。</p></form><div id="delegation-output" class="hidden"></div></section>`;}
function verificationPage(id){const c=TRUST_CASES.find(x=>x.id===id);if(!c)return heading('NOT FOUND','找不到这个验证实验。','请从下面的入口重新选择。')+button('返回使用方法','#trust');trustState={caseId:id,step:0,questions:0,blind:null,judgment:null,source:null,accept:[],recomputed:false};return `<div class="demo-heading"><a href="#trust">返回怎样放心用 AI</a><span class="tag">${c.kind} · 7 步练习</span></div>${heading('跟着例子学检查',c.title,c.desc)}<div class="demo-disclosure">这是编写好的练习，人物、公告和数据都是示例。点击按钮不会向真实 AI 发送消息。</div><nav class="audit-steps" aria-label="验证实验步骤">${TRUST_STEPS.map((s,i)=>`<button data-audit-step="${i}"><b>${i+1}</b><span>${s}</span></button>`).join('')}</nav><div id="audit-stage" tabindex="-1"></div>`;}
function sourceButtons(c){return `<div class="source-tabs">${c.sources.map(s=>`<button class="source-button" data-audit-source="${s.id}" ${s.late&&trustState.step<5?'disabled':''}>${s.id} · ${s.title}${s.late&&trustState.step<5?'（第 6 步提供）':''}</button>`).join('')}</div>`;}
function sourcePanel(c){const s=c.sources.find(s=>s.id===trustState.source)||c.sources[0];return `<aside class="audit-source-panel"><div class="eyebrow">用到的原始材料</div>${sourceButtons(c)}<article id="audit-source-text" class="audit-source-text" aria-live="polite"><span class="badge">${s.id}</span><h3>${s.title}</h3><p class="small-note">${s.meta}</p><blockquote>${s.text}</blockquote><p class="small-note">这份材料只用来练习。实际查资料时，请打开对应的真实公告或文件。</p></article></aside>`;}
function auditRole(role,text,cls=''){return `<section class="audit-message ${cls}"><strong>${role}</strong><p>${esc(text)}</p></section>`;}
function testWidget(version){return `<div class="test-widget" data-test-version="${version}"><div class="toolbar"><strong>清单 ${version} · 实际点点看</strong><button class="quiet" data-reset-widget="${version}">重新测试</button></div>${['证件','雨伞','充电器'].map(x=>`<label><input type="checkbox" data-audit-check> ${x}</label>`).join('')}<div id="audit-counter" role="status">已准备 0 / 3 件</div><p class="small-note">${version==='V1'?'初稿故意没有计数更新。':version==='V2'?'修复稿故意保留了取消勾选的错误。':'按当前实际选中项计数。本次页面内有效。'}</p></div>`;}
function auditStage(){const c=TRUST_CASES.find(x=>x.id===trustState.caseId),n=trustState.step;if(!c||!$('#audit-stage'))return;$$('[data-audit-step]').forEach(b=>{const selected=Number(b.dataset.auditStep)===n;b.classList.toggle('current',selected);if(selected)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});let body='';
 if(n===0)body=`<h2>先看看，这次要请 AI 做什么。</h2><div class="contract-block"><span>要做什么</span><p>${c.goal}</p><span>怎样才算做好</span><p>${c.standard}</p></div><p>这份要求也要给帮忙检查的 AI。大家看的是同一份材料、按同一个要求检查，结果才好比较。</p><div class="callout">整理材料、做草稿，可以让它自己继续。是否能发送、发布或覆盖原文件，要提前说清楚。</div>`;
 if(n===1)body=`<h2>没说清楚的地方，让 AI 问你。</h2><p>比如查开放时间，得先知道是哪一天。看看 AI 会问什么，你又该怎么回答。</p><div id="audit-interview">${c.questions.slice(0,trustState.questions).map(([q,a])=>auditRole('AI 反问',q)+auditRole('你的确认',a,'person')).join('')}</div>${trustState.questions<c.questions.length?`<button class="btn" data-audit-question>${trustState.questions===0?'让 AI 先问一个关键问题':'回答后，再问下一个'}</button>`:'<div class="callout">这些问题问清楚了，就可以先做一版看看。</div>'}`;
 if(n===2){body=`<h2>A 的答案出来了，B 怎样检查？</h2>${auditRole('AI A · 初稿，尚未验证',c.a,'draft')}<h3>${c.blindQuestion}</h3><div class="quiz-options">${c.blindOptions.map((x,i)=>`<button class="quiz-option ${trustState.blind===i?'chosen':''}" data-audit-blind="${i}" aria-pressed="${trustState.blind===i}">${x}</button>`).join('')}</div>${trustState.blind===null?'':trustState.blind===1?auditRole('AI B · 先看同一任务与原始材料后的独立结果',c.b,'independent'):'<p class="feedback incorrect" role="status">这样容易带入 A 的结论或制造假验证。请先让 B 从原材料出发。</p>'}${c.id==='tool-check'?testWidget('V1'):''}<p class="small-note">演示中的“独立”指先不给 A 的答案。真实模型之间仍可能共享知识、来源或记忆，不能保证错误相互独立。</p>`;}
 if(n===3)body=`<h2>两个 AI 说得不一样，先看哪里不同。</h2><div class="claim-ledger">${c.claims.map(([claim,evidence,status,source],i)=>`<article><span class="claim-id">C${i+1}</span><div><h3>${claim}</h3><p>${evidence}</p><span class="evidence-status">${status}</span> <button class="source-jump" data-audit-source="${source}">回查 ${source}</button></div></article>`).join('')}</div>${auditRole('复核者 C 的意见 · 同样需要检查',c.critic,'critic')}<h3>${c.judgment}</h3><div class="quiz-options">${c.options.map((x,i)=>`<button class="quiz-option ${trustState.judgment===i?'chosen':''}" data-audit-judgment="${i}" aria-pressed="${trustState.judgment===i}">${x}</button>`).join('')}</div><div class="feedback ${trustState.judgment===c.correct?'correct':'incorrect'}" role="status">${trustState.judgment===null?'':trustState.judgment===c.correct?c.why:'这条理由还没有通过证据核查。打开原始依据，再判断一次。'}</div>`;
 if(n===4)body=`<h2>改了哪些地方？还有什么没查过？</h2>${auditRole('原版 A · 保留，方便对照',c.a,'draft')}${auditRole('A 回头检查了这条意见',c.why)}${auditRole('第二版 V2 · 按查到的材料修改',c.repaired,'independent')}<div class="callout">刚才的问题改好了，还要看看有没有新资料，数据是不是最新的，以及有没有漏测的操作。</div>${c.id==='tool-check'?testWidget('V2'):''}<details><summary>让 A 回应批评，可以这样说</summary>${template('请保留原版，逐条回应检查者的质疑：接受、拒绝或保留，并给出依据。不要因为对方反对就改掉有证据支持的内容。修订后列版本、修改位置与仍未验证的事项。')}</details>`;
 if(n===5)body=`<h2>${c.retestTitle}</h2><p>${c.retest}</p><button class="btn secondary" data-audit-source="S3">打开本轮新依据 S3</button>${c.id==='tool-check'?testWidget('V2'):c.id==='survey-check'?`<div class="audit-recalculate"><button class="btn" data-audit-calculate>按更新后的 35 份重新计算</button><div id="recalculate-result" class="output ${trustState.recomputed?'':'hidden'}" aria-live="polite">${trustState.recomputed?auditCalculation():''}</div></div>`:''}<div class="callout warn">这时不能沿用上一轮的“通过”。把受影响的结论标回待复验，再修正。多一轮有价值，是因为多了新证据或新测试。</div><details><summary>现在交给 AI 的下一句话</summary>${template('请用这轮新增资料或失败记录复验当前版本。逐条指出哪些旧结论失效，修正正文及所有受影响位置。给出新版本和复验记录；尚未验证的内容继续保留未知。')}</details>`;
 if(n===6)body=`<h2>现在，这个结果可以用了吗？</h2>${auditRole('第三版 V3 · 写清依据和适用范围',c.final,'independent')}${c.id==='tool-check'?testWidget('V3'):''}<h3>由你按实际情况确认</h3><div class="checklist">${c.acceptance.map((x,i)=>`<label><input type="checkbox" data-audit-accept="${i}" ${trustState.accept.includes(i)?'checked':''}>${x}</label>`).join('')}</div><p class="small-note">做过哪项检查，就勾选哪项。没有实际查过的，先留着。</p><div class="audit-decision" id="audit-decision" role="status">${auditDecision(c)}</div><p>${c.stop}</p><div class="actions"><button class="btn secondary" data-audit-export>保存本案例验证记录</button><button class="btn soft" data-audit-unresolved>仍有关键条件没核实</button></div><p class="small-note">无论几个 AI 同意，都不把结论扩大到尚未检查的范围。</p>`;
 $('#audit-stage').innerHTML=`<div class="audit-layout"><section class="card audit-story"><div class="eyebrow">${n+1} / 7 · ${TRUST_STEPS[n]}</div>${body}<details class="audit-help"><summary>“${['验收标准','反问','独立检查','反证','保留未知','复验','在范围内采用'][n]}”听不懂？看一句大白话</summary><p>${['就是先说清怎样才算做好。比如不是“清单很好用”，而是点一个勾，数字会从 0 变成 1。','让 AI 先问你没说清的地方。像请人做饭，先问几个人吃、有没有忌口。','让另一个助手先自己读材料、算一次，不先告诉它你想听的答案。','就是能说明原说法不成立的材料或操作结果。光说“我觉得不对”不算。','还有没弄明白的地方，就明确写出来。不是每个空白都必须猜一个答案。','改好了，再做一次原来出错的操作；资料更新了，就按新资料重新检查。','只相信这次检查实际支持的部分。清单计数通过，不代表保存功能也已通过。'][n]}</p></details></section>${sourcePanel(c)}</div><div class="demo-bottom"><button class="btn secondary" data-audit-move="-1" ${n===0?'disabled':''}>上一步</button><span>有不同说法，就回到材料里找答案</span>${n<6?'<button class="btn" data-audit-move="1">下一步</button>':button('回到更多练习','#trust/practice')}</div>`;
}
function auditCalculation(){return [13,12,10].map((n,i)=>`${['图书馆','宿舍','教室'][i]}：${n} ÷ 35 × 100% = ${(n/35*100).toFixed(1)}%`).join('\n')+'\n人数合计：35；显示占比合计：100.0%\n这是对汇总 v2 的复算，不代表已核查原始答卷的去重过程。';}
function auditDecision(c){return trustState.accept.length===c.acceptance.length?'已勾选全部检查：可在本练习列明的材料和范围内采用，不代表普遍正确。':`还有 ${c.acceptance.length-trustState.accept.length} 项未确认：先保留待验，不急着写“全部可信”。`;}
function moveAudit(n){trustState.step=Math.max(0,Math.min(6,n));if(trustState.step<5&&trustState.source==='S3')trustState.source='S1';auditStage();$('#audit-stage').focus({preventScroll:true});if($('#audit-stage').getBoundingClientRect().top<0)$('#audit-stage').scrollIntoView({block:'start'});}
function initTrust(){if($('#audit-stage'))auditStage();if($('#delegation-form'))$('#delegation-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget),v=(key,label)=>String(data.get(key)||'').trim()||`[待补充：${label}]`;const base=`任务：${v('goal','成果')}\n对象：${v('audience','使用者')}\n材料与版本：${v('sources','原始材料')}\n验收：${v('criteria','可检查条件')}\n哪些事要先问我：${v('boundary','可自主行动与需确认动作')}`;const packs=[['第一段：请 A 问清楚，再试做',base+'\n先说说你理解我要做什么，哪些信息是确定的，哪些还只是猜测。缺少重要信息时，一次问我一个问题。先做一小部分给我看，确认后在说好的范围内继续。做好后给我文件和出处，告诉我实际检查了什么、还有什么没查过。不要编造来源，也不要把没测试过的地方写成通过。'],['第二段：请 B 自己检查，先不看 A 的答案',base+'\n这是独立检查阶段，先只使用任务和原始材料。我暂不提供 A 的结论。请独立核对、复算或实测；不能使用工具时写未实测，给人可执行步骤。结果列证据位置、日期、范围与缺口。'],['第三段 · 发给 B：比较两个答案',base+'\n你已经独立检查过材料，现在给你 A 的输出和出处：[粘贴]。请与你刚才的结果逐项比较，编号列出一致、不一致和没查清的地方。每条不同意见都说明依据，找不到就直接说。不要为了反对而编造。我会把你的检查意见复制给 A。'],['第四段 · 回到 A 的对话：回应意见并修改',base+'\n这是 B 的检查意见：[粘贴第三步的检查结果]。请保留你原来的版本，逐项核对这些意见。哪些接受、哪些不接受、哪些还没查清，都说明出处或实际测试结果。修正有依据的问题，给修改后的版本和改动清单。我会把它们再交给 B 检查。'],['第五段 · 再发给 B：检查修改后的版本',base+'\n这是 A 修改后的结果：[附新文件并写版本名]，以及 A 的回应：[粘贴]。请对照你此前指出的问题，重新检查，也检查改动影响的其他内容。写出所用材料版本、操作或算式、应该得到的结果和实际结果。没法实际检查的地方标明未验证。重要问题还没解决时先停下来补资料，不靠重复争论下结论。']];$('#delegation-output').classList.remove('hidden');$('#delegation-output').innerHTML='<div class="callout">这五段需要你按顺序复制到对应的 AI 对话里，页面不会自动让它们互相发消息。B 先自己检查，再看 A 的答案；把 B 的意见带回 A，最后把修改稿交回 B。每个 AI 都要拿到需要的原始材料。</div>'+packs.map(([h,p])=>`<h3 class="pack-title">${h}</h3>${template(p)}`).join('');};}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const c=TRUST_CASES.find(x=>x.id===trustState.caseId);if(!c||!$('#audit-stage'))return;
 if(b.dataset.auditStep!==undefined)moveAudit(Number(b.dataset.auditStep));
 if(b.dataset.auditMove!==undefined)moveAudit(trustState.step+Number(b.dataset.auditMove));
 if(b.hasAttribute('data-audit-question')){trustState.questions=Math.min(c.questions.length,trustState.questions+1);auditStage();}
 if(b.dataset.auditBlind!==undefined){trustState.blind=Number(b.dataset.auditBlind);auditStage();}
 if(b.dataset.auditJudgment!==undefined){trustState.judgment=Number(b.dataset.auditJudgment);auditStage();}
 if(b.dataset.auditSource!==undefined){const s=c.sources.find(x=>x.id===b.dataset.auditSource);if(!s||s.late&&trustState.step<5)return;trustState.source=s.id;$('.audit-source-panel').outerHTML=sourcePanel(c);$('#audit-source-text').setAttribute('tabindex','-1');$('#audit-source-text').focus({preventScroll:true});if(innerWidth<1100)$('#audit-source-text').scrollIntoView({block:'nearest',behavior:'smooth'});}
 if(b.hasAttribute('data-audit-calculate')){trustState.recomputed=true;$('#recalculate-result').classList.remove('hidden');$('#recalculate-result').textContent=auditCalculation();}
 if(b.dataset.resetWidget){b.closest('.test-widget').outerHTML=testWidget(b.dataset.resetWidget);}
 if(b.hasAttribute('data-audit-unresolved')){trustState.accept=[];$$('[data-audit-accept]').forEach(x=>x.checked=false);$('#audit-decision').textContent='暂不采用：请补充缺失资料或交给能实际核实的人。停止增加无证据的保证，保留问题清单。';}
 if(b.hasAttribute('data-audit-export')){const text=`AI 生活课堂 · 预设验证实验记录\n${c.title}\n\n所有材料与对话均为虚构。以下为预设案例路径，不是对真实信息的外部验证。\n\n任务：${c.goal}\n验收：${c.standard}\n\nAI A：${c.a}\nAI B 独立结果：${c.b}\nC 的质疑：${c.critic}\n核查：${c.why}\n\n修订 V2：${c.repaired}\n复验：${c.retest}\n修订 V3：${c.final}\n\n来源：\n${c.sources.map(s=>`${s.id} ${s.title} / ${s.meta}\n${s.text}`).join('\n\n')}\n\n学习者自行勾选的检查记录（非独立认证）：\n${c.acceptance.map((x,i)=>`${trustState.accept.includes(i)?'[已勾选]':'[未勾选]'} ${x}`).join('\n')}\n\n${auditDecision(c)}\n停止条件：${c.stop}`;const u=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`验证练习记录-${c.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);toast('已准备验证练习记录。');}
});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-audit-accept')){trustState.accept=$$('[data-audit-accept]:checked').map(x=>Number(x.dataset.auditAccept));$('#audit-decision').textContent=auditDecision(TRUST_CASES.find(x=>x.id===trustState.caseId));}if(e.target.hasAttribute('data-audit-check')){const w=e.target.closest('.test-widget'),v=w.dataset.testVersion;let n=0;if(v==='V2'){w.dataset.count=String(Number(w.dataset.count||0)+1);n=Number(w.dataset.count);}else if(v==='V3')n=$$('[data-audit-check]:checked',w).length;$('#audit-counter',w).textContent=`已准备 ${n} / 3 件`;}});
